import{_ as e,a as n}from"./chunks/dataflow-converter-dialog.CaG_3Yb6.js";import{_ as o,o as a,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Data flow – values, conversion and calculation","description":"","frontmatter":{"title":"Data flow – values, conversion and calculation"},"headers":[],"relativePath":"en/projects/grafik-visual-studio/datenfluss.md","filePath":"en/projects/grafik-visual-studio/datenfluss.md","lastUpdated":1793198184000}'),s={name:"en/projects/grafik-visual-studio/datenfluss.md"};function d(l,t,u,c,g,p){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="ha-grafik-–-data-flow" tabindex="-1">HA Grafik – Data flow <a class="header-anchor" href="#ha-grafik-–-data-flow" aria-label="Permalink to &quot;HA Grafik – Data flow&quot;">​</a></h1><p>From <strong>0.1.287</strong>, <strong>all widgets</strong> can be hidden using <strong>WIDGET → In Runtime verstecken</strong> (Hide in runtime). Save the project afterwards. A hidden Number widget still supplies Math inputs; a hidden Math box still calculates. The checkbox does not disable value sources and works independently of z-index. Everything remains editable in the editor.</p><p>Updates through Studio <strong>0.1.285</strong>: SVG lines and Value connections support <strong>Line → Vertical starting position</strong>. Vertical orthogonal lines first run vertically, then turn left or right at target height. Point handles use a 6 px drag threshold and do not move a multi-selection. Hold <strong>Alt</strong> to move a docked line as a whole. Regular SVG lines at <strong>z-index −100 or lower</strong> are also invisible in runtime while retaining their values. They can connect <strong>Number → Math</strong>; see the setup and zero-value example in <a href="./svg-linebox-math">LineBox Math</a>.</p><p>From Studio <strong>0.1.141</strong>, the dedicated <strong>HA Grafik – Data flow</strong> palette contains three widgets. Calculations and conversions run in the browser on each display computer. Home Assistant supplies entity values; internal processing requires no additional HA entities. The visualization must remain open.</p><table tabindex="0"><thead><tr><th>Widget</th><th>Editor</th><th>Runtime</th></tr></thead><tbody><tr><td><strong>Value connection</strong></td><td>Simple SVG line without animation, directed from start to destination</td><td>Invisible; continues passing values</td></tr><tr><td><strong>Value converter</strong></td><td>Widget and dedicated radio-button dialog with input/output types and preview</td><td>Always invisible; conversion remains active</td></tr><tr><td><strong>Value calculation</strong></td><td>Same editor as <a href="./svg-linebox-math">SVG LineBox Math</a>, with four calculations and ports A–P</td><td>Invisible by default; calculations and outputs remain active</td></tr></tbody></table><p>Value connection and Value calculation internally reuse the SVG-Line and SVG-LineBox-Math types, preserving docking, movement, copying, project import/export and shared calculation logic. SVG LineBox Math also supports <strong>Hide in runtime</strong>. Disable this option on Value calculation if you want to display its calculation widget.</p><h2 id="connecting-a-source" tabindex="-1">Connecting a source <a class="header-anchor" href="#connecting-a-source" aria-label="Permalink to &quot;Connecting a source&quot;">​</a></h2><p><img src="'+e+'" alt="Single output point with position radio buttons"></p><p>Since 0.1.154, CSS General remains required for these widgets too; the other CSS groups are optional.</p><p>From <strong>0.1.143</strong>, optional CSS groups are disabled by default on new data-flow widgets; Value calculation also disables <strong>Display</strong> by default. Calculation and conversion remain enabled. Enable these groups when needed; disabled CSS fields are omitted from exports. New Value connections have no arrowheads at either end. Previously saved widgets retain their settings.</p><ol><li>On a widget with an entity or preview value, enable <strong>Enable output point</strong> under <strong>Data flow</strong>. Use the <strong>Top</strong>, <strong>Bottom</strong>, <strong>Right</strong> or <strong>Left</strong> radio buttons to select the center of that edge; right is the default. This single output works independently of <strong>Docking points</strong> and can be disabled. Set its separate color under <strong>Settings → Output point</strong>. The point is visible only in the editor; forwarding stays active in runtime. Widgets without an available value, such as plain borders, provide no value. Existing docking configurations are preserved; LineBox, LineBox Math and converters continue using their own ports.</li><li>Add a <strong>Value connection</strong>: start at the source output and end at the converter or receiver input. Values always follow this direction, even without visible arrowheads; animation is disabled.</li><li>Open <strong>Edit conversion</strong>, select the converter&#39;s input and output, and enable <strong>Enable selected input/output docking points</strong>. New ports remain disabled until explicitly enabled.</li><li>Choose a conversion and check the preview. For <strong>Number</strong> and <strong>String</strong> in the Basic set, select <strong>Enable input point</strong> under <strong>Data flow</strong>. For other regular receivers, enable <strong>Receive value from data flow</strong> and their input port. Number can alternatively use its existing numeric docking input, which continues summing multiple numeric values.</li></ol><p>A converter and general data-flow input accept <strong>exactly one source per input</strong>. Multiple outgoing connections can distribute a result to different receivers. The converter does not sum strings or switch states. LineBox Math retains its own summation of multiple numeric connections.</p><h3 id="input-point-on-number-and-string" tabindex="-1">Input point on Number and String <a class="header-anchor" href="#input-point-on-number-and-string" aria-label="Permalink to &quot;Input point on Number and String&quot;">​</a></h3><p>From Studio <strong>0.1.274</strong>, both Basic widgets offer a dedicated input point under <strong>Data flow</strong>. Like the output, it supports <strong>Top</strong>, <strong>Bottom</strong>, <strong>Right</strong> and <strong>Left</strong>; left is the default. The input works independently of <strong>Docking points</strong>. Enabling it makes the widget receive the connected source value in both editor and runtime. Existing incoming connections follow when you change sides. An additionally enabled output can forward the received value.</p><p>Disabling data-flow input restores the widget&#39;s entity or preview value. Data-flow points are visible only in the editor.</p><h2 id="converter-dialog" tabindex="-1">Converter dialog <a class="header-anchor" href="#converter-dialog" aria-label="Permalink to &quot;Converter dialog&quot;">​</a></h2><p><img src="'+n+'" alt="Converter dialog with radio buttons and preview for temperature text to number"></p><table tabindex="0"><thead><tr><th>Conversion</th><th>Settings and output</th></tr></thead><tbody><tr><td>Number → text</td><td>0–10 decimal places, decimal point/comma, optional unit</td></tr><tr><td>Text → number</td><td>Recognize decimal points/commas and trailing units; output a number</td></tr><tr><td>Switch state → number</td><td>On → 1, off → 0; optional inversion</td></tr><tr><td>Number → switch state</td><td>On when value ≥ threshold, otherwise off; optional inversion</td></tr><tr><td>Switch state → text</td><td>Custom on/off text; optional inversion</td></tr><tr><td>Normalize switch state</td><td>Accept <code>on/off</code>, <code>true/false</code> or <code>1/0</code>; output real Booleans, numbers or <code>on/off</code> text</td></tr><tr><td>Scale number</td><td><code>value * factor + offset</code>, optional target unit; e.g. °C → °F using factor 1.8 and offset 32</td></tr></tbody></table><p>Switch-state parsing ignores case and surrounding whitespace. Unknown states are reported. Only settings relevant to the selected conversion are shown. Changes apply after <strong>Apply</strong> and support Undo.</p><h2 id="units-and-errors" tabindex="-1">Units and errors <a class="header-anchor" href="#units-and-errors" aria-label="Permalink to &quot;Units and errors&quot;">​</a></h2><p><code>23,5 °C</code> splits into numeric value <strong>23.5</strong> and unit <strong>°C</strong>. A plain value uses HA&#39;s <code>unit_of_measurement</code> metadata or the widget unit. If neither exists, configure a fallback unit. A unit already present in the text takes precedence and is never appended twice. <strong>Include unit in text</strong> is optional. Unit recognition alone does not perform conversion; explicitly select <strong>Scale number</strong> and configure factor, offset and target unit.</p><p>Empty values, <code>unknown</code>, <code>unavailable</code>, invalid numbers, unknown switch states, inactive inputs, multiple sources and feedback cycles produce errors. No value is output by default. <strong>Enable fallback on error</strong> starts disabled; enabling it outputs the configured fallback text, without automatically converting that text into a number or Boolean.</p><p>Example: temperature display <code>23,5 °C</code> → <strong>Text → number</strong> converter → Value calculation <code>A * 2</code> → Number <strong>47.0</strong>. Runtime shows only the temperature display and Number. Results are passed internally and are not automatically stored in Home Assistant. The current basic threshold has no hysteresis and switches directly at its boundary.</p>',23)])])}const b=o(s,[["render",d]]);export{f as __pageData,b as default};
